/* @lc app=leetcode id=3213 lang=kotlin */ class Solution { fun hv(ph: Array<LongArray>, pw: Array<LongArray>, i: Int, L: Int): Long = ((((ph[0][i] - ph[0][i - L] * pw[0][L]) % 1_000_000_007L + 1_000_000_007L) % 1_000_000_007L) shl 32) or (((ph[1][i] - ph[1][i - L] * pw[1][L]) % 998_244_353L + 998_244_353L) % 998_244_353L) fun minimumCost(target: String, words: Array<String>, costs: IntArray): Int = target.length.let { n -> longArrayOf(1_000_000_007L, 998_244_353L).let { md -> longArrayOf(131L, 137L).let { bs -> Array(2) { k -> target.runningFold(0L) { h, c -> (h * bs[k] + c.code) % md[k] }.toLongArray() }.let { ph -> Array(2) { k -> generateSequence(1L) { it * bs[k] % md[k] }.take(n + 1).toList().toLongArray() }.let { pw -> HashMap<Long, Int>().also { m -> words.indices.forEach { i -> words[i].fold(0L to 0L) { (a, b), c -> ((a * 131 + c.code) % 1_000_000_007L) to ((b * 137 + c.code) % 998_244_353L) }.let { (a, b) -> m.merge((a shl 32) or b, costs[i]) { x, y -> minOf(x, y) } } } }.let { m -> words.map { it.length }.distinct().let { lens -> ArrayList<Long>().also { it.add(0L) }.let { dp -> (1..n).forEach { i -> dp.add(lens.filter { it <= i && dp[i - it] < Long.MAX_VALUE / 4 }.mapNotNull { L -> m[hv(ph, pw, i, L)]?.let { dp[i - L] + it } }.minOrNull() ?: (Long.MAX_VALUE / 4)) }.let { dp[n].let { if (it >= Long.MAX_VALUE / 4) -1 else it.toInt() } } } } } } } } } } }